grade = input("Ingrese una letra de calificacion en mayusculas: ") 
#Paso 2: Determinar e imprimir el rango numerico para la calificacion ingresada
if grade == "A" : 
    print("La puntuacion es mayor o igual a 90.")
elif grade == "B" :
    print("La puntuacion esta en el rango [80-90).")
elif grade == "C" :
    print("La puntuacion esta en el rango [70-80).")
elif grade == "D" :
    print("La puntuacion esta en el rango [60-70).")
else :
    print("La puntuacion es menor que 60.")

